dirs=[(1,0),(-1,0),(0,1),(0,-1)]
def gen_long(s):
 for p in s:
  x,y=p
  for dx,dy in dirs:
   for k in range(2,8):
    dst=(x+dx*k,y+dy*k)
    if dst not in valid: break
    if dst in s: continue
    between={(x+dx*j,y+dy*j) for j in range(1,k)}
    crossed=between&s
    if crossed:
     ns=(s-{p}-crossed)|{dst}
     yield ns,(p,dst)
